using System.Net;using System.Net.Http.Json;using System.Text.Json;using Xunit;
namespace EduForge.Tests;
public class WorkspaceFeatureTests {
 static async Task Login(HttpClient c,string email){var r=await c.PostAsJsonAsync("/api/auth/register",new{email,name="Преподаватель",password="Correct horse battery staple!"});r.EnsureSuccessStatusCode();c.DefaultRequestHeaders.Add("Cookie",r.Headers.GetValues("Set-Cookie").Single().Split(';')[0]);}
 static async Task<JsonElement> Json(HttpResponseMessage r){Assert.True(r.IsSuccessStatusCode,await r.Content.ReadAsStringAsync());return await r.Content.ReadFromJsonAsync<JsonElement>();}
 [Fact] public async Task InvitationApprovalDuplicatesRevocationAndOwnership(){using var f=new ApiFactory();using var owner=f.Browser();using var other=f.Browser();using var student=f.Browser();await Login(owner,"owner@example.test");await Login(other,"other@example.test");var group=await Json(await owner.PostAsJsonAsync("/api/groups",new{name="Группа",description=""}));var id=group.GetProperty("id").GetString();Assert.Equal(HttpStatusCode.NotFound,(await other.PostAsync($"/api/groups/{id}/invitation",null)).StatusCode);var invite=await Json(await owner.PostAsync($"/api/groups/{id}/invitation",null));var token=invite.GetProperty("token").GetString();await Json(await student.PostAsJsonAsync("/api/enroll/"+token,new{firstName="Алина",lastName="Ахметова"}));Assert.Equal(HttpStatusCode.Conflict,(await student.PostAsJsonAsync("/api/enroll/"+token,new{firstName="алина",lastName="ахметова"})).StatusCode);var state=await owner.GetFromJsonAsync<JsonElement>($"/api/groups/{id}/invitation");var request=state.GetProperty("requests")[0].GetProperty("id").GetString();Assert.Equal(HttpStatusCode.NoContent,(await owner.PostAsync($"/api/groups/{id}/invitation/requests/{request}/approve",null)).StatusCode);var actual=await owner.GetFromJsonAsync<JsonElement>($"/api/groups/{id}");Assert.Single(actual.GetProperty("students").EnumerateArray());await owner.DeleteAsync($"/api/groups/{id}/invitation");Assert.Equal(HttpStatusCode.NotFound,(await student.GetAsync("/api/enroll/"+token)).StatusCode);}
 [Fact] public async Task ProfileDisciplinesValidateAndPersist(){using var f=new ApiFactory();using var c=f.Browser();await Login(c,"profile@example.test");var good=new{name="Новое имя",bio="Преподаю Python",age=25,country="Казахстан",city="Кызылорда",avatarUrl="",disciplines=new[]{"Python","Python","HTML"}};Assert.Equal(HttpStatusCode.NoContent,(await c.PutAsJsonAsync("/api/profile",good)).StatusCode);var profile=await c.GetFromJsonAsync<JsonElement>("/api/profile");Assert.Equal("Новое имя",profile.GetProperty("name").GetString());Assert.Equal(2,profile.GetProperty("disciplines").GetArrayLength());Assert.Equal(HttpStatusCode.BadRequest,(await c.PutAsJsonAsync("/api/profile",new{name="",bio="",age=5,country="",city="",avatarUrl="",disciplines=Array.Empty<string>()})).StatusCode);}
 [Fact] public async Task ModerationPreventsPrematurePublicationAndChecksAdmin(){using var f=new ApiFactory{ModerationEnabled=true,AdminEmail="admin@example.test"};using var admin=f.Browser();using var author=f.Browser();await Login(admin,"admin@example.test");await Login(author,"author@example.test");var material=await Json(await author.PostAsJsonAsync("/api/materials",new{title="Урок",subject="Python",content="Учебный материал"}));var id=material.GetProperty("id").GetString();var pending=await Json(await author.PostAsync($"/api/materials/{id}/publication",null));Assert.Equal("Pending",pending.GetProperty("status").GetString());Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync($"/api/library/{id}")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await author.GetAsync("/api/moderation")).StatusCode);var queue=await admin.GetFromJsonAsync<JsonElement>("/api/moderation");var review=queue[0].GetProperty("id").GetString();Assert.Equal(HttpStatusCode.NoContent,(await admin.PostAsJsonAsync("/api/moderation/"+review,new{approve=true,reason=""})).StatusCode);Assert.Equal(HttpStatusCode.OK,(await author.GetAsync($"/api/library/{id}")).StatusCode);}
 [Fact] public async Task UpdatesSaveLocalVersionInsteadOfDestroyingEdits(){using var f=new ApiFactory();using var author=f.Browser();using var reader=f.Browser();await Login(author,"source@example.test");await Login(reader,"copy@example.test");var source=await Json(await author.PostAsJsonAsync("/api/materials",new{title="Урок",subject="Python",content="Исходник"}));var id=source.GetProperty("id").GetString();await Json(await author.PostAsync($"/api/materials/{id}/publication",null));var copy=await Json(await reader.PostAsync($"/api/library/{id}/copy",null));var copyId=copy.GetProperty("id").GetString();await Json(await reader.PutAsJsonAsync($"/api/materials/{copyId}",new{title="Моя копия",subject="Python",content="Мои правки"}));await Json(await author.PutAsJsonAsync($"/api/materials/{id}",new{title="Новый урок",subject="Python",content="Новая версия"}));await Json(await author.PostAsync($"/api/materials/{id}/publication",null));var preview=await reader.GetFromJsonAsync<JsonElement>($"/api/copies/material/{copyId}");Assert.True(preview.GetProperty("hasUpdate").GetBoolean());var revision=preview.GetProperty("revision");Assert.Equal(HttpStatusCode.Conflict,(await reader.PostAsJsonAsync($"/api/copies/material/{copyId}/update",new{revision,preserveLocal=false})).StatusCode);Assert.Equal(HttpStatusCode.NoContent,(await reader.PostAsJsonAsync($"/api/copies/material/{copyId}/update",new{revision,preserveLocal=true})).StatusCode);var all=await reader.GetFromJsonAsync<JsonElement>("/api/materials");Assert.Contains(all.EnumerateArray(),x=>x.GetProperty("content").GetString()=="Мои правки");Assert.Contains(all.EnumerateArray(),x=>x.GetProperty("content").GetString()=="Новая версия");}
}
